#include "StdAfx.h"#include "SafetyManager.h"#include <rsuNoNames.h>#include <SafetyManagerStruct.h>#include <rsuFormats.h>extern KNoName g_IOs;int KSafetyManager::StepTL( double dtS ){  DWORD ID = 0;  CBase* pBase = NULL;  int nFcs = 0;  const char* pszName;  int added = 0;  while( g_IOs.WhileBase( ID, -1, &pBase, &pszName, &nFcs ) )  {    switch( pBase->ID_CLASS )    {    case W_SMDI::TypeID:      {        W_SMDI *W = (W_SMDI*)pBase;        W->PV = W->PVFL;      }      break;    case W_SMDICOM::TypeID:      {        W_SMDICOM *W = (W_SMDICOM*)pBase;        W->PV = W->PVFL;      }      break;    default:      continue;    }  }  mList.Timer( this, dtS );#if 0  char szTmpName[64];  for( UINT n = 0, nCount(mList.Count()); n < nCount; n++ )  {    IFscStorage::SVarInfo vars[10] = { 0 };    LPCSTR pPntName = NULL;    SFscBase* obj = mList.Item(n);    const int C = mList.GetVars( this, obj, vars, _countof(vars), &pPntName );    if( !C )      continue;    if( !pPntName || !*pPntName )    {      sprintf_s( szTmpName, "%d", obj->uniNum );      pPntName = szTmpName;    }    for( int i=0; i<C; ++i )    {      if( !vars[i].val )        continue;      char szVal[32];      switch( vars[i].val->eType )      {      default:        ASSD(0);        break;      case enumValueBol:        strcpy_s( szVal, vars[i].val->bVal ? "1" : "0" );        break;      case enumValueDbl:        DblToStr(szVal, vars[i].val->dVal);        break;      case enumValueInt:        sprintf_s(szVal, "%d", vars[i].val->nVal);        break;      case enumValueChr:        sprintf_s(szVal, "%d", vars[i].val->cVal);        break;      }    }  }#endif  ID = 0;  while( g_IOs.WhileBase( ID, -1, &pBase, &pszName, &nFcs ) )  {    switch( pBase->ID_CLASS )    {    case W_SMDO::TypeID:      {        W_SMDO *W = (W_SMDO*)pBase;        W->OP = W->OPFL;      }      break;    case W_SMDOCOM::TypeID:      {        W_SMDOCOM *W = (W_SMDOCOM*)pBase;        W->PV = W->PVFL;      }      break;    default:      continue;    }  }  return 0;}